    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("gelu_tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        out = torch.empty(x.shape, device=x.device, dtype=x.dtype)
        n = x.numel()
        if n == 0:
            return out
        module = _get_ptx_module()
        block = 256
        grid = ((n + block - 1) // block, 1, 1)
        module.launch(
            "gelu_tanh_kernel",
            grid=grid,
            block=(block, 1, 1),
            arguments=[x, out, u64(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
